#include <stdio.h>
#include <string.h>

#define MAXW 105
#define MAXH 105
#define INF 1000000000

static int W, H;
static char g[MAXH][MAXW];
static int dp[MAXH][MAXW][MAXW];

/*
dp[y1][y2][x] = minimum number of square carpets needed to cover
all scratched cells in rows [y1..y2] and columns [x..W-1].

Transition:
- If column x has no scratched cells in rows [y1..y2], skip it.
- Otherwise, either:
  1) cover some scratched cell in column x with a square of side s
     starting at column x and spanning rows [r..r+s-1], where the whole
     square contains only scratched cells;
     then solve left-above, left-below, and right parts.
  2) split horizontally at some row k.
*/

static int solve(int y1, int y2, int x) {
    if (y1 > y2 || x >= W) return 0;
    int *memo = &dp[y1][y2][x];
    if (*memo != -1) return *memo;

    int has = 0;
    for (int y = y1; y <= y2; y++) {
        if (g[y][x] == '1') {
            has = 1;
            break;
        }
    }
    if (!has) return *memo = solve(y1, y2, x + 1);

    int ans = INF;

    for (int k = y1; k < y2; k++) {
        int v = solve(y1, k, x) + solve(k + 1, y2, x);
        if (v < ans) ans = v;
    }

    for (int r = y1; r <= y2; r++) {
        if (g[r][x] != '1') continue;

        int maxs = y2 - r + 1;
        if (W - x < maxs) maxs = W - x;

        for (int s = 1; s <= maxs; s++) {
            int ok = 1;
            for (int yy = r; yy < r + s && ok; yy++) {
                for (int xx = x; xx < x + s; xx++) {
                    if (g[yy][xx] != '1') {
                        ok = 0;
                        break;
                    }
                }
            }
            if (!ok) break; /* larger s also impossible */

            int v = 1;
            v += solve(y1, r - 1, x);
            v += solve(r + s, y2, x);
            v += solve(r, r + s - 1, x + s);

            if (v < ans) ans = v;
        }
    }

    return *memo = ans;
}

int main(void) {
    while (scanf("%d %d", &W, &H) == 2) {
        if (W == 0 && H == 0) break;

        for (int i = 0; i < H; i++) {
            scanf("%s", g[i]);
        }

        memset(dp, -1, sizeof(dp));
        printf("%d\n", solve(0, H - 1, 0));
    }
    return 0;
}

