#include <bits/stdc++.h>
using namespace std;

/*
We need the minimum number of axis-aligned square carpets to cover all '1' cells,
with the restriction that no carpet may cover any '0' cell. Carpets may overlap.

Classic exact cover / DP on subsets is too large for general grids, but this problem
has a key structure:

Any valid square carpet corresponds to an all-1 square in the grid.
If one square is strictly contained in another, using the smaller one is never better
than using the larger one for covering cells. Therefore, it is enough to consider
only maximal all-1 squares (not contained in any larger all-1 square).

Then the task becomes:
Choose the minimum number of these candidate squares whose union covers all 1-cells.

This is minimum set cover, NP-hard in general, but the original problem instances are
small enough for branch-and-bound with bitsets, which is the intended approach.

Implementation details:
- Enumerate all all-1 squares using DP for largest square ending at each cell.
- Mark every square that exists.
- Keep only maximal squares (not contained in another all-1 square).
- Compress all scratched cells into indices [0..K-1].
- For each candidate square, build a bitset of covered scratched cells.
- Remove dominated candidates: if A's coverage is subset of B's coverage, A is useless.
- DFS branch-and-bound:
  * If uncovered empty => update answer.
  * Lower bound by ceil(uncovered_count / max_cover_per_square).
  * Pick an uncovered cell that is contained in the fewest candidate squares.
  * Branch on selecting each square covering that cell.

Dynamic bitset is implemented with vector<uint64_t>.
*/

struct Square {
    int x, y, s; // top-left (x,y), size s
    vector<unsigned long long> bits;
};

static inline bool subset_bits(const vector<unsigned long long>& a,
                               const vector<unsigned long long>& b) {
    // a subset of b ?
    for (size_t i = 0; i < a.size(); ++i) {
        if ((a[i] & ~b[i]) != 0ULL) return false;
    }
    return true;
}

static inline int popcount_bits(const vector<unsigned long long>& a) {
    int r = 0;
    for (auto v : a) r += __builtin_popcountll(v);
    return r;
}

static inline vector<unsigned long long> andnot_bits(const vector<unsigned long long>& a,
                                                     const vector<unsigned long long>& b) {
    vector<unsigned long long> r(a.size());
    for (size_t i = 0; i < a.size(); ++i) r[i] = a[i] & ~b[i];
    return r;
}

int W, H;
vector<string> g;
vector<Square> cand;
vector<vector<int>> cellToSquares;
int K;
int bestAns;

void dfs(const vector<unsigned long long>& uncovered, int used) {
    if (used >= bestAns) return;

    int rem = popcount_bits(uncovered);
    if (rem == 0) {
        bestAns = used;
        return;
    }

    int maxCover = 0;
    for (const auto& sq : cand) {
        int c = 0;
        for (size_t i = 0; i < uncovered.size(); ++i)
            c += __builtin_popcountll(sq.bits[i] & uncovered[i]);
        maxCover = max(maxCover, c);
    }
    if (maxCover == 0) return;

    int lb = (rem + maxCover - 1) / maxCover;
    if (used + lb >= bestAns) return;

    // Choose an uncovered cell with minimum branching.
    int chosenCell = -1;
    int bestDeg = INT_MAX;

    for (int block = 0; block < (int)uncovered.size(); ++block) {
        unsigned long long v = uncovered[block];
        while (v) {
            int b = __builtin_ctzll(v);
            int id = block * 64 + b;
            if (id < K) {
                int deg = 0;
                for (int si : cellToSquares[id]) {
                    bool covers = false;
                    for (size_t i = 0; i < uncovered.size(); ++i) {
                        if (cand[si].bits[i] & uncovered[i]) { covers = true; break; }
                    }
                    if (covers) deg++;
                }
                if (deg < bestDeg) {
                    bestDeg = deg;
                    chosenCell = id;
                    if (deg <= 1) break;
                }
            }
            v &= v - 1;
        }
        if (bestDeg <= 1) break;
    }

    if (chosenCell == -1) {
        bestAns = min(bestAns, used);
        return;
    }

    vector<pair<int,int>> options; // (-newly_covered, square_index)
    for (int si : cellToSquares[chosenCell]) {
        int c = 0;
        for (size_t i = 0; i < uncovered.size(); ++i)
            c += __builtin_popcountll(cand[si].bits[i] & uncovered[i]);
        if (c > 0) options.push_back({-c, si});
    }
    sort(options.begin(), options.end());

    for (auto [negc, si] : options) {
        auto nxt = andnot_bits(uncovered, cand[si].bits);
        dfs(nxt, used + 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (cin >> W >> H) {
        if (W == 0 && H == 0) break;

        g.assign(H, "");
        for (int i = 0; i < H; ++i) cin >> g[i];

        // DP for largest all-1 square ending at (y,x)
        vector<vector<int>> dp(H, vector<int>(W, 0));
        int maxS = 0;
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                if (g[y][x] == '1') {
                    dp[y][x] = 1;
                    if (x > 0 && y > 0) {
                        dp[y][x] = 1 + min({dp[y-1][x], dp[y][x-1], dp[y-1][x-1]});
                    }
                    maxS = max(maxS, dp[y][x]);
                }
            }
        }

        // Mark existence of every all-1 square by size and top-left.
        vector<vector<vector<char>>> exists(maxS + 1);
        for (int s = 1; s <= maxS; ++s) {
            exists[s].assign(H - s + 1, vector<char>(W - s + 1, 0));
        }
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                for (int s = 1; s <= dp[y][x]; ++s) {
                    int ty = y - s + 1;
                    int tx = x - s + 1;
                    exists[s][ty][tx] = 1;
                }
            }
        }

        // Keep only maximal squares (not contained in any larger existing square).
        cand.clear();
        for (int s = 1; s <= maxS; ++s) {
            for (int y = 0; y + s <= H; ++y) {
                for (int x = 0; x + s <= W; ++x) {
                    if (!exists[s][y][x]) continue;
                    bool contained = false;
                    for (int t = s + 1; t <= maxS && !contained; ++t) {
                        int y1 = max(0, y + s - t);
                        int y2 = min(y, H - t);
                        int x1 = max(0, x + s - t);
                        int x2 = min(x, W - t);
                        for (int yy = y1; yy <= y2 && !contained; ++yy) {
                            for (int xx = x1; xx <= x2; ++xx) {
                                if (exists[t][yy][xx]) {
                                    contained = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (!contained) cand.push_back({x, y, s, {}});
                }
            }
        }

        // Compress scratched cells.
        vector<vector<int>> id(H, vector<int>(W, -1));
        K = 0;
        for (int y = 0; y < H; ++y)
            for (int x = 0; x < W; ++x)
                if (g[y][x] == '1')
                    id[y][x] = K++;

        int B = (K + 63) >> 6;
        for (auto& sq : cand) {
            sq.bits.assign(B, 0ULL);
            for (int y = sq.y; y < sq.y + sq.s; ++y) {
                for (int x = sq.x; x < sq.x + sq.s; ++x) {
                    int idx = id[y][x];
                    if (idx >= 0) sq.bits[idx >> 6] |= 1ULL << (idx & 63);
                }
            }
        }

        // Remove dominated candidates.
        vector<int> alive(cand.size(), 1);
        for (int i = 0; i < (int)cand.size(); ++i) if (alive[i]) {
            for (int j = 0; j < (int)cand.size(); ++j) if (i != j && alive[j]) {
                if (subset_bits(cand[i].bits, cand[j].bits)) {
                    bool strict = false;
                    for (int b = 0; b < B; ++b) {
                        if (cand[i].bits[b] != cand[j].bits[b]) {
                            strict = true;
                            break;
                        }
                    }
                    if (strict) {
                        alive[i] = 0;
                        break;
                    }
                }
            }
        }
        vector<Square> filtered;
        for (int i = 0; i < (int)cand.size(); ++i) if (alive[i]) filtered.push_back(move(cand[i]));
        cand.swap(filtered);

        cellToSquares.assign(K, {});
        for (int i = 0; i < (int)cand.size(); ++i) {
            for (int b = 0; b < B; ++b) {
                unsigned long long v = cand[i].bits[b];
                while (v) {
                    int t = __builtin_ctzll(v);
                    int idx = b * 64 + t;
                    if (idx < K) cellToSquares[idx].push_back(i);
                    v &= v - 1;
                }
            }
        }

        vector<unsigned long long> uncovered(B, ~0ULL);
        if (K % 64) uncovered.back() = (1ULL << (K % 64)) - 1ULL;
        if (K == 0) {
            cout << 0 << '\n';
            continue;
        }

        bestAns = K; // worst case: each 1x1
        dfs(uncovered, 0);
        cout << bestAns << '\n';
    }

    return 0;
}

