public class Main {
    static int[] match;
    static boolean[] visited;
    static List<List<Integer>> graph;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int w = sc.nextInt();
            int h = sc.nextInt();
            if (w == 0 && h == 0) break;
            int[][] grid = new int[h][w];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    grid[i][j] = sc.nextInt();
                }
            }

            int[][] rowId = new int[h][w];
            int[][] colId = new int[h][w];
            int rowCnt = 0, colCnt = 0;

            // Assign row IDs for horizontal segments of 1's
            for (int i = 0; i < h; i++) {
                int j = 0;
                while (j < w) {
                    if (grid[i][j] == 1) {
                        rowCnt++;
                        while (j < w && grid[i][j] == 1) {
                            rowId[i][j] = rowCnt;
                            j++;
                        }
                    } else {
                        j++;
                    }
                }
            }

            // Assign column IDs for vertical segments of 1's
            for (int j = 0; j < w; j++) {
                int i = 0;
                while (i < h) {
                    if (grid[i][j] == 1) {
                        colCnt++;
                        while (i < h && grid[i][j] == 1) {
                            colId[i][j] = colCnt;
                            i++;
                        }
                    } else {
                        i++;
                    }
                }
            }

            // Build bipartite graph: left side = rows, right side = cols
            graph = new ArrayList<>();
            for (int i = 0; i <= rowCnt; i++) graph.add(new ArrayList<>());
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (grid[i][j] == 1) {
                        int r = rowId[i][j];
                        int c = colId[i][j];
                        graph.get(r).add(c);
                    }
                }
            }

            // Maximum bipartite matching
            match = new int[colCnt + 1];
            Arrays.fill(match, 0);
            int result = 0;
            for (int u = 1; u <= rowCnt; u++) {
                visited = new boolean[colCnt + 1];
                if (dfs(u)) result++;
            }
            System.out.println(result);
        }
        sc.close();
    }

    static boolean dfs(int u) {
        for (int v : graph.get(u)) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] == 0 || dfs(match[v])) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

