        hor_id = [[-1]*w for _ in range(h)]
        hor_count = 0
        for i in range(h):
            j = 0
            while j < w:
                if grid[i][j] == 1:
                    hor_count += 1
                    while j < w and grid[i][j] == 1:
                        hor_id[i][j] = hor_count
                        j += 1
