                    j += 1

        # Assign IDs to vertical segments
        ver_id = [[-1]*w for _ in range(h)]
        ver_count = 0
        for j in range(w):
            i = 0
            while i < h:
                if grid[i][j] == 1:
                    ver_count += 1
                    while i < h and grid[i][j] == 1:
                        ver_id[i][j] = ver_count
                        i += 1
                else:
                    i += 1

        # Build adjacency list for bipartite matching
        adj = [[] for _ in range(hor_count + 1)]
        for i in range(h):
            for j in range(w):
                if grid[i][j] == 1:
                    u = hor_id[i][j]
                    v = ver_id[i][j]
                    adj[u].append(v)

        # Hopcroft-Karp for maximum matching
        match_h = [0] * (hor_count + 1)
        match_v = [0] * (ver_count + 1)
        dist = [0] * (hor_count + 1)

        def bfs():
            q = deque()
            for u in range(1, hor_count+1):
                if match_h[u] == 0:
                    dist[u] = 0
                    q.append(u)
                else:
                    dist[u] = float('inf')
            dist[0] = float('inf')
            while q:
                u = q.popleft()
                if dist[u] < dist[0]:
                    for v in adj[u]:
                        if dist[match_v[v]] == float('inf'):
                            dist[match_v[v]] = dist[u] + 1
                            q.append(match_v[v])
            return dist[0] != float('inf')

        def dfs(u):
            if u != 0:
                for v in adj[u]:
                    if dist[match_v[v]] == dist[u] + 1 and dfs(match_v[v]):
                        match_h[u] = v
                        match_v[v] = u
                        return True
                dist[u] = float('inf')
                return False
            return True

        matching = 0
        while bfs():
            for u in range(1, hor_count+1):
                if match_h[u] == 0 and dfs(u):
                    matching += 1

        results.append(str(matching))

    sys.stdout.write("\n".join(results))

