import sys
from functools import lru_cache

def solve_case(w, h, grid):
    # Convert each row to bitmask of scratched cells
    rows = []
    for r in grid:
        mask = 0
        for j, ch in enumerate(r):
            if ch == '1':
                mask |= 1 << j
        rows.append(mask)

    # Prefix sums for O(1) square validity checks
    ps = [[0] * (w + 1) for _ in range(h + 1)]
    for i in range(h):
        row_acc = 0
        for j in range(w):
            row_acc += 1 if grid[i][j] == '1' else 0
            ps[i + 1][j + 1] = ps[i][j + 1] + row_acc

    def rect_sum(r1, c1, r2, c2):
        return ps[r2][c2] - ps[r1][c2] - ps[r2][c1] + ps[r1][c1]

    # All valid all-1 squares starting at each cell
    squares_at = [[[] for _ in range(w)] for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if grid[i][j] != '1':
                continue
            maxs = min(h - i, w - j)
            for s in range(1, maxs + 1):
                if rect_sum(i, j, i + s, j + s) == s * s:
                    cover = [0] * h
                    bits = ((1 << s) - 1) << j
                    for r in range(i, i + s):
                        cover[r] = bits
                    squares_at[i][j].append(tuple(cover))
                else:
                    break

    initial_state = tuple(rows)

    @lru_cache(maxsize=None)
    def dp(state):
        # Find first uncovered scratched cell
        for i in range(h):
            if state[i]:
                lsb = state[i] & -state[i]
                j = lsb.bit_length() - 1
                break
        else:
            return 0

        best = 10**9
        for cover in squares_at[i][j]:
            new_state = list(state)
            ok = False
            for r in range(h):
                if cover[r]:
                    if new_state[r] & cover[r]:
                        ok = True
                    new_state[r] &= ~cover[r]
            if ok:
                best = min(best, 1 + dp(tuple(new_state)))
        return best

    return dp(initial_state)

def main():
    data = sys.stdin.read().strip().split()
    out = []
    p = 0
    while p < len(data):
